import {enterBattle} from './combat-core.mjs';
export const replacementPids=b=>b.over?[]:(b.teams||[]).filter(t=>t.mons[t.active]?.hp<=0&&t.mons.some(m=>m.hp>0)).map(t=>t.pid);
export function replacementRound(b,chart,random=Math.random,raid=false){const waiting=replacementPids(b);if(!waiting.length)return undefined;b.pendingReplacements=waiting;b.phase='replacement';if(!waiting.every(pid=>{const t=b.teams.find(t=>t.pid===pid),a=b.actions?.[pid];return Number.isInteger(a?.swap)&&a.swap!==t.active&&t.mons[a.swap]?.hp>0}))return null;
 const events=[],field=b.field||={sides:{},seen:{}};field.sides||={};field.seen||={};field.chart=chart;
 const foe=raid?{pid:'boss',active:b.enemyIndex||0,mons:b.enemyParty||[b.boss]}:null;if(foe)foe.mons[foe.active]=b.boss;
 for(const pid of waiting){const t=b.teams.find(t=>t.pid===pid),enemy=raid?foe:b.teams.find(o=>o!==t);t.active=b.actions[pid].swap;t.switchTurn=b.turn;t.entered=true;const mon=t.mons[t.active];events.push({kind:'swap',pid,key:mon.key,mon:structuredClone(mon)});field.sides[pid]||={hazards:{}};enterBattle(t,enemy,field,events,random);if(mon.hp<=0)events.push({kind:'ko',pid,key:mon.key})}
 delete field.chart;b.pendingReplacements=replacementPids(b);b.phase=b.pendingReplacements.length?'replacement':'turn';b.actions={};b.sequence=(b.sequence||0)+1;
 if(b.teams.some(t=>!t.mons.some(m=>m.hp>0))){if(!raid){b.over=true;b.pendingReplacements=[];b.winner=b.teams.find(t=>t.mons.some(m=>m.hp>0))?.pid||null}else if(!b.teams.some(t=>t.mons.some(m=>m.hp>0))){b.over=true;b.pendingReplacements=[];b.win=false}}return events;
}
export function replacementMarkup(b,controller){if(b.over)return ''; const me=controller.me(),revive=b.revivalPids?.includes(me.pid),pending=b.pendingReplacements||[],needed=pending.includes(me.pid);if(!needed)return pending.length?`<div class="replacement-wait" role="status">Un dresseur choisit son prochain Pokémon…<button data-act="exit-battle">Quitter le combat</button></div>`:'';return `<section class="replacement-choice" role="region" aria-label="Choisir le Pokémon remplaçant"><span class="eyebrow">${revive?'BÉNÉDICTION · CHOISIR UN ALLIÉ À RANIMER':me.mons[me.active].hp<=0?'TON POKÉMON EST K.O.':'CHANGEMENT DE PARTENAIRE'}</span><h3>Qui prends-tu pour la suite ?</h3><p>Choisis un partenaire en état de combattre. Cette entrée ne consomme pas de tour.</p><div>${me.mons.map((mon,slot)=>`<button data-act="battle-swap" data-slot="${slot}" ${(revive?mon.hp>0:mon.hp<=0)||slot===me.active||b.actions?.[me.pid]?'disabled':''}>${controller.g.image(mon.key)}<b>${mon.name}</b><small>${Math.ceil(mon.hp)} / ${mon.max} PV</small></button>`).join('')}</div><button class="replacement-exit" data-act="exit-battle">Quitter le combat</button></section>`}
